//! The .slp reader vs the shipping C reader (gw_replay.c rp_parse / rp_load, oracle/replay_oracle.sh).
//! Synthetic corpus: tests/data/slp (committed, generated by oracle/gen_slp.py). Real replays: the
//! sample listed in tests/data/replay_real_oracle.txt is looked up under REAL_SLP_DIR (default the
//! workspace Gang-Steals folder); the test is skipped when that folder is absent.

use melee_data::replay::{parse, summary_line};
use std::path::{Path, PathBuf};

fn check(oracle: &str, find: impl Fn(&str) -> Option<PathBuf>) -> usize {
    let mut n = 0;
    for want in oracle.lines() {
        let name = want.split('\t').next().unwrap();
        let path = find(name).unwrap_or_else(|| panic!("missing {name}"));
        let bytes = std::fs::read(&path).unwrap();
        let got = summary_line(name, &parse(&bytes, true));
        assert_eq!(want, got, "{name}");
        n += 1;
    }
    n
}

#[test]
fn synthetic_corpus_matches_the_c() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/slp");
    let n = check(include_str!("data/replay_oracle.txt"), |n| Some(dir.join(n)));
    assert!(n >= 90);
    // sanity: the corpus covers both outcomes
    let t = include_str!("data/replay_oracle.txt");
    assert!(t.contains("active=0") && t.contains("active=1") && t.contains("online=1") && t.contains("skin="));
}

#[test]
fn real_replays_match_the_c() {
    let root = std::env::var("REAL_SLP_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|_| Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../../Gang-Steals"));
    if !root.is_dir() {
        eprintln!("skipped: {} not found", root.display());
        return;
    }
    let n = check(include_str!("data/replay_real_oracle.txt"), |n| Some(root.join(n)));
    assert!(n >= 200);
}

#[test]
fn first_frame_zero_does_not_write_out_of_bounds() {
    // the C overruns its input array here (see gen_slp.py); the port skips the event
    let r = parse(include_bytes!("data/slp/oneframe.slp"), false);
    assert!(r.is_ok());
}
